package thaumcraft.common.entities;
import java.util.*;
import net.minecraft.world.entity.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.entity.EntityAttributeCreationEvent;
import thaumcraft.common.entities.monster.boss.*;
import thaumcraft.common.entities.monster.tainted.*;
import thaumcraft.common.entities.projectile.*;
@EventBusSubscriber(modid="thaumcraft",bus=EventBusSubscriber.Bus.MOD)
public final class Mob8BossRegistries {
    public static EntityType<EntityCultistLeader> CULTIST_LEADER;public static EntityType<EntityCultistPortalGreater> PORTAL_GREATER;
    public static EntityType<EntityEldritchGolem> ELDRITCH_GOLEM;public static EntityType<EntityEldritchWarden> ELDRITCH_WARDEN;public static EntityType<EntityTaintacleGiant> TAINTACLE_GIANT;
    public static EntityType<EntityTaintCrawler> TAINT_CRAWLER;public static EntityType<EntityTaintacle> TAINTACLE;public static EntityType<EntityTaintacleSmall> TAINTACLE_SMALL;public static EntityType<EntityTaintSwarm> TAINT_SWARM;public static EntityType<EntityTaintSeed> TAINT_SEED;public static EntityType<EntityTaintSeedPrime> TAINT_SEED_PRIME;
    public static EntityType<EntityHomingShard> HOMING_SHARD;public static EntityType<EntityRiftBlast> RIFT_BLAST;
    private Mob8BossRegistries(){}
    private static <T extends Entity> EntityType<T> mob(String name,EntityType.EntityFactory<T> factory,float width,float height,float eye,boolean fire){boolean stationary=name.equals("cultist_portal_greater")||name.startsWith("taint_")&&!name.equals("taint_crawler")||name.startsWith("taintacle");boolean slow=name.equals("cultist_portal_greater")||name.startsWith("taint_seed");var builder=EntityType.Builder.of(factory,MobCategory.MONSTER).sized(width,height).eyeHeight(eye).clientTrackingRange(name.equals("taintacle_giant")?6:4).updateInterval(slow?20:3).setShouldReceiveVelocityUpdates(!stationary);if(fire)builder.fireImmune();return builder.build("thaumcraft:"+name);}
    public static Map<String,EntityType<?>> createEntityTypes(){var map=new LinkedHashMap<String,EntityType<?>>();map.put("cultist_leader",CULTIST_LEADER=mob("cultist_leader",EntityCultistLeader::new,.75F,2.25F,1.9125F,false));map.put("cultist_portal_greater",PORTAL_GREATER=mob("cultist_portal_greater",EntityCultistPortalGreater::new,1.5F,3,2.55F,true));map.put("eldritch_golem",ELDRITCH_GOLEM=mob("eldritch_golem",EntityEldritchGolem::new,1.75F,3.5F,3,true));map.put("eldritch_warden",ELDRITCH_WARDEN=mob("eldritch_warden",EntityEldritchWarden::new,1.5F,3.5F,3.1F,false));map.put("taintacle_giant",TAINTACLE_GIANT=mob("taintacle_giant",EntityTaintacleGiant::new,1.1F,6,5.1F,false));map.put("taint_crawler",TAINT_CRAWLER=mob("taint_crawler",EntityTaintCrawler::new,.5F,.4F,.1F,false));map.put("taintacle",TAINTACLE=mob("taintacle",EntityTaintacle::new,.8F,3,2.55F,false));map.put("taintacle_small",TAINTACLE_SMALL=mob("taintacle_small",EntityTaintacleSmall::new,.22F,1,.85F,false));map.put("taint_swarm",TAINT_SWARM=mob("taint_swarm",EntityTaintSwarm::new,2,2,1.7F,false));map.put("taint_seed",TAINT_SEED=mob("taint_seed",EntityTaintSeed::new,1.5F,1.25F,1.0625F,false));map.put("taint_seed_prime",TAINT_SEED_PRIME=mob("taint_seed_prime",EntityTaintSeedPrime::new,2,2,1.7F,false));map.put("homing_shard",HOMING_SHARD=EntityType.Builder.<EntityHomingShard>of(EntityHomingShard::new,MobCategory.MISC).sized(.25F,.25F).clientTrackingRange(4).updateInterval(20).build("thaumcraft:homing_shard"));map.put("rift_blast",RIFT_BLAST=EntityType.Builder.<EntityRiftBlast>of(EntityRiftBlast::new,MobCategory.MISC).sized(.25F,.25F).clientTrackingRange(4).updateInterval(20).build("thaumcraft:rift_blast"));return map;}
    public static boolean isTainted(EntityType<?> type){return type==TAINT_CRAWLER||type==TAINTACLE||type==TAINTACLE_SMALL||type==TAINTACLE_GIANT||type==TAINT_SWARM||type==TAINT_SEED||type==TAINT_SEED_PRIME||type.is(net.minecraft.tags.TagKey.create(net.minecraft.core.registries.Registries.ENTITY_TYPE,net.minecraft.resources.ResourceLocation.parse("thaumcraft:tainted")));}
    @SubscribeEvent public static void attributes(EntityAttributeCreationEvent event){event.put(CULTIST_LEADER,EntityCultistLeader.createAttributes().build());event.put(PORTAL_GREATER,EntityCultistPortalGreater.createAttributes().build());event.put(ELDRITCH_GOLEM,EntityEldritchGolem.createAttributes().build());event.put(ELDRITCH_WARDEN,EntityEldritchWarden.createAttributes().build());event.put(TAINTACLE_GIANT,EntityTaintacleGiant.createAttributes().build());event.put(TAINT_CRAWLER,EntityTaintCrawler.createAttributes().build());event.put(TAINTACLE,EntityTaintacle.createAttributes().build());event.put(TAINTACLE_SMALL,EntityTaintacleSmall.createAttributes().build());event.put(TAINT_SWARM,EntityTaintSwarm.createAttributes().build());event.put(TAINT_SEED,EntityTaintSeed.createAttributes().build());event.put(TAINT_SEED_PRIME,EntityTaintSeedPrime.createAttributes().build());}
}
